class Plecak {
  items = [];
  spakuj(nazwa) {
    this.items.push(nazwa);
  }
}

const plecak = new Plecak();
plecak.spakuj("namiot");
plecak.spakuj("mapa");
plecak.spakuj("latarka");
console.log(plecak.items); // ["namiot", "mapa", "latarka"]

class Profil {
  widocznosc = "publiczny";
  powiadomienia = true;
}

const profil = new Profil();
console.log(profil.widocznosc);   // "publiczny"
console.log(profil.powiadomienia); // true

class PrzyciskLike {
  polubienia = 0;
  kliknij = () => {
    this.polubienia++;
  };
}

const przycisk = new PrzyciskLike();
const wyciagnietyKliknij = przycisk.kliknij;
wyciagnietyKliknij();
wyciagnietyKliknij();
console.log(przycisk.polubienia); // 2 - dziala mimo wyrwania z obiektu

// Pole klasy (bezposrednio w ciele klasy, np. items = []) jest odpowiednie,
// gdy wartosc poczatkowa jest STALA i NIEZALEZNA od argumentow przekazanych
// do konstruktora - np. licznik zawsze zaczyna od 0, tablica zawsze zaczyna
// jako pusta.
//
// Ustawienie pola w constructor (this.imie = imie) jest odpowiednie, gdy
// wartosc ZALEZY od argumentu przekazanego przez uzytkownika przy tworzeniu
// instancji - np. imie osoby rozni sie dla kazdej instancji i MUSI byc
// przekazane z zewnatrz, nie moze miec jednej, sztywnej wartosci domyslnej.

class Ustawienia {
  jezyk = "pl";
  motyw = "jasny";
  dzwiek = true;
}

const ustawieniaA = new Ustawienia();
const ustawieniaB = new Ustawienia();

ustawieniaA.motyw = "ciemny";
console.log(ustawieniaA.motyw); // "ciemny"
console.log(ustawieniaB.motyw); // "jasny" - niezalezna instancja

class Timer {
  sekundy = 0;
  tick = () => {
    this.sekundy++;
  };
}

const timer = new Timer();
for (let i = 0; i < 5; i++) {
  timer.tick();
}
console.log(timer.sekundy); // 5

class Ankieta {
  odpowiedzi = [];
  constructor(pytanie) {
    this.pytanie = pytanie;
  }
  dodajOdpowiedz(tekst) {
    this.odpowiedzi.push(tekst);
  }
}

const ankieta = new Ankieta("Jaki jest twoj ulubiony kolor?");
ankieta.dodajOdpowiedz("niebieski");
ankieta.dodajOdpowiedz("zielony");
ankieta.dodajOdpowiedz("czerwony");
console.log(ankieta.odpowiedzi); // ["niebieski", "zielony", "czerwony"]

