class Formularz {
  bledy = [];
  wartosci = {};

  ustaw(pole, wartosc) {
    this.wartosci[pole] = wartosc;
    if (wartosc === "") this.bledy.push("puste pole: " + pole);
  }

  czyPoprawny() {
    return this.bledy.length === 0;
  }
}

const f = new Formularz();
f.ustaw("imie", "Ala");
console.log(f.czyPoprawny()); // -> true
f.ustaw("email", "");
console.log(f.czyPoprawny()); // -> false
console.log(f.bledy);         // -> ["puste pole: email"]

